<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Core/PublicPage.php';
if(!empty($_SESSION['user_id'])&&!Security::enforceAuthenticatedSession($config)){Security::destroySession();}require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Services/Authorization.php';
$user=null;$mine=[];try{if(!empty($_SESSION['user_id'])){$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if($user){$q=$db->prepare('SELECT reference_code,subject,status,created_at FROM foi_requests WHERE user_id=:uid ORDER BY created_at DESC LIMIT 15');$q->execute(['uid'=>$user['user_id']]);$mine=$q->fetchAll(PDO::FETCH_ASSOC);}}}catch(Throwable $e){error_log('FOI page: '.$e->getMessage());}
pageHeader('Freedom of Information','Submit a request for public records through the portal.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">PUBLIC ACCOUNTABILITY</p><h1>Freedom of Information</h1><p>Use this channel to request access to records held by the Barangay, subject to applicable laws, privacy protections, and records availability.</p></div></section><section class="section"><div class="content-layout"><article class="content-panel"><div class="notice warning"><b>Demonstration channel</b><p>This online form records a request for staff review. It is not yet integrated with a formally designated FOI receiving officer, official FOI tracking system, or approved FOI manual. Verify the Barangay’s official procedure before public use.</p></div>
<?php if(!$user): ?><p><a class="action-primary" href="<?= Security::e(url('login.php')) ?>">Sign in to submit an FOI request</a> or <a href="<?= Security::e(url('register.php')) ?>">create an account</a>.</p><?php else: ?><form class="portal-form" method="post" action="<?= Security::e(url('foi_submit.php')) ?>"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><label>Request subject *<input name="subject" maxlength="180" required></label><label>Records requested *<textarea name="requested_records" rows="6" maxlength="5000" required placeholder="Describe the records, date range, department, or subject as clearly as possible."></textarea></label><label>Purpose (optional)<textarea name="purpose" rows="3" maxlength="1000"></textarea></label><label class="check-row"><input type="checkbox" name="privacy_ack" value="1" required> I understand that requests may be limited or redacted to protect personal, confidential, or legally exempt information.</label><button class="auth-submit" type="submit">Submit FOI request</button></form><?php endif; ?></article><aside class="side-panel"><h2>Request guidance</h2><ul class="info-list"><li>Be specific about the records requested.</li><li>Do not request personal information about another person without lawful authority.</li><li>Staff may contact you for clarification.</li><li>Submission does not guarantee release of all requested records.</li></ul></aside></div>
<?php if($mine): ?><div class="section-inner"><h2>Your FOI requests</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Subject</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach($mine as $r): ?><tr><td><?= Security::e($r['reference_code']) ?></td><td><?= Security::e($r['subject']) ?></td><td><?= Security::e($r['status']) ?></td><td><?= Security::e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
</section></main><?php pageFooter();
